const byTitle = new Map<string, MatterSupport>();
for (const entry of MATTER_SUPPORT) for (const title of entry.titles) {
  if (byTitle.has(title)) throw new Error(`Duplicate matter support: ${title}`);
  byTitle.set(title, entry.support);
}
export function getMatterSupport(title: string): MatterSupport {
  const support = byTitle.get(title);
  if (!support) throw new Error(`Missing matter-specific service offer: ${title}`);
  return support;
}
